package com.ecommerce.cart.service; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/cart") public class CartController { final CartRepository repo; CartController(CartRepository r){repo=r;} record Req(@NotNull UUID customerId,@NotNull UUID productId,@Min(1) int quantity,@NotNull @Positive BigDecimal unitPrice){} @GetMapping("/{customerId}") List<CartItem> get(@PathVariable UUID customerId){return repo.findByCustomerId(customerId);} @PostMapping("/items") CartItem add(@RequestBody Req x){CartItem i=repo.findByCustomerIdAndProductId(x.customerId(),x.productId()).orElseGet(CartItem::new);i.setCustomerId(x.customerId());i.setProductId(x.productId());i.setQuantity(i.getQuantity()+x.quantity());i.setUnitPrice(x.unitPrice());return repo.save(i);} @DeleteMapping("/{customerId}") void clear(@PathVariable UUID customerId){repo.deleteByCustomerId(customerId);} }